				function artifactType_changed () {

					var val = form.getConfig("artifactType");
					if ( val == null ) {
						return;
					} 

					var selclass = form.getConfig("classType");

					if ( val.equalsIgnoreCase("RELATIONSHIP") ) {
						form.getControl("relSrc").setEnabled(false);						
						form.getControl("relTrg").setEnabled(false);

						if ((selclass != null) 
                && (!selclass.startsWith("RELATION")) 
                && (!selclass.equals("ALL"))) {
						    form.getControl("classType").setText("");
            }
					} else {
						form.getControl("relSrc").setEnabled(true);						
						form.getControl("relTrg").setEnabled(true);

						if ((selclass != null) && (selclass.startsWith("RELATION"))) {
						    form.getControl("classType").setText("");
            }
					}   					

					update_controls();
				}

				function 	update_controls() {
					var co = form.getConfigObject();
					if ( co == null ) {
						return;
					} 

					var cmode = co.getParent().getMode();
					if ( cmode.equalsIgnoreCase("AddOnly") || 
                cmode.equalsIgnoreCase("Delete") ||
                cmode.equalsIgnoreCase("Update")) {
            //form.getControl("classType").setText("ALL");
            form.getControl("classType").setEnabled(false);
						form.getControl("relSrc").setEnabled(false);						
						form.getControl("relTrg").setEnabled(false);					
					} 

					form.updateControl ("classType");
				}				

				artifactType_changed();
				update_controls();

// tests if a connection to a remote system can be established by a Connector
function checkConnection() {
	var conn = form.loadConnector();

	conn.initialize (null);
	var exceptionText = null;

	exceptionText = conn.checkDbConnection();
	var jdbcParams = "";
	jdbcParams += conn.getJdbcUrl() + ", ";
	jdbcParams += conn.getJdbcDriver() + ", ";
	jdbcParams += conn.getDbUsername() ;
	conn.terminate();

	if (exceptionText == null) {
		form.alert(Messages.getMessage("ASForms.Connection.Success", jdbcParams));
	} else {
		// log the values of the jdbc parameters used in the connecion attempt
		form.alert(Messages.getMessage("ASForms.Connection.Failure", jdbcParams, exceptionText));
	}	
}

// returns the Class types available to the CCMDB Connector
function getClassTypes() {
	var CCMDB_CONN_ARTIFACTTYPE = "artifactType";
	var CCMDB_CONN_CLASSTYPE = "classType";
	var IDML_MODE = "idmlMode";

	var idmlMode = form.getConfig(IDML_MODE);
	if ( idmlMode == null ) {
		idmlMode = "false";
	}

	var artifactType = form.getConfig(CCMDB_CONN_ARTIFACTTYPE);

  var connector = form.loadConnector(); 	
	connector.initialize (null);	
	connector.checkDbConnection();
	var classTypes = connector.getClassTypes(artifactType);

	if (classTypes == null || classTypes.isEmpty()) {
		form.alert(Messages.getString("ASForms.No.ClassTypes.Were.Found"));
		return;
	}

  var dlg = new com.ibm.tdi.eclipse.dialogs.ComboInputDialog(form.getShell(), Messages.getString("ASForms.Select.ClassType"), Messages.getString("ASForms.Select.ClassType"), classTypes);	
	dlg.open();
  var selection = dlg.getValue();

	if (selection != null) {
		form.setConfig (CCMDB_CONN_CLASSTYPE, selection.toString());
		form.updateControl (CCMDB_CONN_CLASSTYPE);
	}
}
